-- --------------------------------------------------------
-- 5. Synchronize Sequences for Medflow
-- --------------------------------------------------------
INSERT INTO medflow_sequences (table_name, next_id)
VALUES
  ('definition', (SELECT COALESCE(MAX("DefNum"), 0) + 1 FROM "definition")),
  ('feesched', (SELECT COALESCE(MAX("FeeSchedNum"), 0) + 1 FROM "feesched")),
  ('procedurecode', (SELECT COALESCE(MAX("CodeNum"), 0) + 1 FROM "procedurecode")),
  ('fee', (SELECT COALESCE(MAX("FeeNum"), 0) + 1 FROM "fee"))
ON CONFLICT (table_name) DO UPDATE
SET next_id = EXCLUDED.next_id;

COMMIT;
